But I'm not entirely happy with it. I may try to update the OSD for the frames directly instead.

This diff should accomplish the same thing except slightly better

```diff
diff --git a/video/out/vo_gpu_next.c b/video/out/vo_gpu_next.c
index b517d44b67..45a5705c0a 100644
--- a/video/out/vo_gpu_next.c
+++ b/video/out/vo_gpu_next.c
@@ -949,6 +949,8 @@ static void video_screenshot(struct vo *vo, struct voctrl_screenshot *args)
     struct mp_image *mpi = image->user_data;
     struct mp_rect src = p->src, dst = p->dst;
     struct mp_osd_res osd = p->osd_res;
+    mix.num_frames = 1; // make sure we only render this frame
+
     if (!args->scaled) {
         src = dst = (struct mp_rect) {0, 0, mpi->params.w, mpi->params.h};
         osd = (struct mp_osd_res) {
@@ -956,6 +958,20 @@ static void video_screenshot(struct vo *vo, struct voctrl_screenshot *args)
             .h = mpi->params.h,
             .display_par = 1.0,
         };
+
+        if (args->subs) {
+            struct frame_priv *fp = mpi->priv;
+            update_overlays(vo, osd, mpi->pts, OSD_DRAW_SUB_ONLY, &fp->subs, image);
+            fp->osd_sync = 0; // regenerate this OSD on the next normal frame
+        }
+    }
+
+    int prev_num_overlays = image->num_overlays;
+    if (!args->subs && image->num_overlays) {
+        // We're forced to flush the cache in this case to prevent any
+        // previously rendered OSDs from becoming visible in the screenshot
+        pl_renderer_flush_cache(p->rr);
+        image->num_overlays = 0;
     }
 
     // Create target FBO, try high bit depth first
@@ -998,12 +1014,8 @@ static void video_screenshot(struct vo *vo, struct voctrl_screenshot *args)
     apply_crop(image, src, mpi->params.w, mpi->params.h);
     apply_crop(&target, dst, fbo->params.w, fbo->params.h);
 
-    int osd_flags = 0;
-    if (!args->subs)
-        osd_flags |= OSD_DRAW_OSD_ONLY;
-    if (!args->osd)
-        osd_flags |= OSD_DRAW_SUB_ONLY;
-    update_overlays(vo, osd, 0, osd_flags, &p->osd_state, &target);
+    if (args->osd)
+        update_overlays(vo, osd, mpi->pts, OSD_DRAW_OSD_ONLY, &p->osd_state, &target);
 
     if (!pl_render_image_mix(p->rr, &mix, &target, &p->params)) {
         MP_ERR(vo, "Failed rendering frame!\n");
@@ -1026,6 +1038,7 @@ static void video_screenshot(struct vo *vo, struct voctrl_screenshot *args)
     // fall through
 done:
     pl_tex_destroy(gpu, &fbo);
+    image->num_overlays = prev_num_overlays;
 }
 
 static int control(struct vo *vo, uint32_t request, void *data)
```

Although I noticed that for some reason, the subs always seem to be rendering with the wrong colorspace on screenshots, even when taking screenshots at video resolution (in which case it shouldn't be bypassing the mixer cache). I'll investigate it further. But maybe that makes the first diff preferable to the second one.
